// Request-options-shaped npm-static residual: aliased target mutation,
// ordered partial sources, nullish skips, returned target identity, and a
// nested refcounted overwrite.
const defaults = {
  model: "base",
  enabled: false,
  retries: 1,
  headers: { authorization: "old" },
};

export function buildRequestOptions() {
  const target = { ...defaults };
  /** @type {typeof target} */
  const result = /** @type {typeof target} */ (Object.assign(
    target,
    { model: "first" },
    null,
    { enabled: true, retries: 3 },
    undefined,
    { model: "request", headers: { authorization: "new" } },
  ));
  if (result !== target) throw new Error("Object.assign lost target identity");
  return target;
}
